if (ctx.device == null) { ctx.device = new HashMap(); }
if (ctx.source != null && ctx.source.mac != null) {
  def m = ctx.source.mac.toString().toLowerCase().replace('-', ':');
  if (m.length() >= 8) { ctx.oui = m.substring(0, 8); }
}

if (ctx.m_26_14 == null) { ctx.m_26_14 = new HashMap(); }
if (ctx.device == null) { ctx.device = new HashMap(); }
boolean ot = false;

// --- OUI enrich results ---
if (ctx._oui != null) {
  if (ctx._oui.vendor != null) { ctx.device.vendor = ctx._oui.vendor; }
  if (ctx._oui.device_class != null) { ctx.device.class = ctx._oui.device_class; }
  if (ctx._oui.ot == true) { ot = true; }
}

// --- DHCP vendor-class (option 55/60) refinement when OUI gave no class ---
if (ctx.dhcp != null && ctx.dhcp.vendor_class != null) {
  def vc = ctx.dhcp.vendor_class.toString().toLowerCase();
  if (ctx.device.class == null) {
    if (vc.contains('msft')) { ctx.device.class = 'endpoint'; }
    else if (vc.contains('android')) { ctx.device.class = 'mobile'; }
    else if (vc.contains('udhcp') || vc.contains('busybox')) { ctx.device.class = 'iot_sensor'; }
  }
}

// --- OT industrial-protocol tagging ---
def otProtos = ['modbus','dnp3','s7comm','enip','ethernetip','cip','iec104','iec-104','bacnet','profinet','opcua','opc-ua'];
if (ctx.network != null && ctx.network.protocol != null) {
  def proto = ctx.network.protocol.toString().toLowerCase();
  if (otProtos.contains(proto)) {
    ot = true;
    ctx.m_26_14.ot_protocol = proto;
    if (ctx.device.class == null) { ctx.device.class = 'plc'; }
  }
}
ctx.m_26_14.ot = ot;

// --- identity fields ---
def ip = (ctx.source != null) ? ctx.source.ip : null;
def mac = (ctx.source != null) ? ctx.source.mac : null;
def observed = ctx.m_26_14.observed_via;

// --- host.* for the Entity Store host engine ---
if (ctx.host == null) { ctx.host = new HashMap(); }
if (ctx.host.name == null) {
  if (mac != null) { ctx.host.name = 'netdev-' + mac.toString().replace(':', ''); }
  else if (ip != null) { ctx.host.name = 'netdev-' + ip; }
}
if (ctx.host.ip == null && ip != null) { ctx.host.ip = ip; }
if (ctx.host.mac == null && mac != null) { ctx.host.mac = mac; }

// --- asset.* (unified M-26-14 asset model, unmanaged until reconciled to HWAM) ---
if (ctx.asset == null) { ctx.asset = new HashMap(); }
ctx.asset.id = (mac != null) ? mac : ip;
if (ctx.asset.name == null) { ctx.asset.name = ctx.host.name; }
ctx.asset.source = observed;
ctx.asset.managed = false;
if (ctx.containsKey('@timestamp')) { ctx.asset.last_seen = ctx['@timestamp']; }

// --- related.ip for pivoting ---
def rip = new ArrayList();
if (ip != null) { rip.add(ip); }
if (ctx.destination != null && ctx.destination.ip != null) { rip.add(ctx.destination.ip); }
if (rip.size() > 0) {
  if (ctx.related == null) { ctx.related = new HashMap(); }
  ctx.related.ip = rip;
}

// --- M-26-14 coverage flags: network-observed devices are unmanaged by definition ---
ctx.m_26_14.managed = false;
ctx.m_26_14.device_source = 'network-observed';
if (observed != null) { ctx.m_26_14.hwam_source = observed; }
